rss.channel:
{{ site.title }}
{{ site.base_url | safe }}/
{{ site.description }}

{% if updated %}{{ updated.rfc2822 }}{% endif %}
{% for page in pages %}


  {{ page.title }}
  {{ site.base_url | safe }}{{ page.url | safe }}
  {{ site.base_url | safe }}{{ page.url | safe }}
  {% if page.date %}{{ page.date.rfc2822 }}{% endif %}
  {% for category in page.categories %}{{ category.name }}{% endfor %}
  {# An item's HTML belongs in the description as escaped text, which is what autoescaping gives. #}
  {{ page.content }}

{% endfor %}
